import paramiko

from taf.config.testline.gnb import CloudBts
from re import sub
from taf.ue import ue as taf_ue
from robot.libraries.BuiltIn import BuiltIn
from robot.utils import timestr_to_secs

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_result, log_to_console, \
    log_warning
from taf.rfrl.l3_call.btslog.btslog_factory import BtsLogFactory
from taf.rfrl.l3_call.connection.api_connection.api_connection_factory import ApiConnectionFactory
from taf.rfrl.l3_call.exceptions import IncorrectCellId, IncorrectDataTransferDirection, \
    UeNetworkModeMissing, UnrecognizedUeNetworkMode, ConflictingUeNetworkModes, PingStatisticsNotFound, \
    PingExecutionFailed, PingValidationFailed


class CallManagerCore:
    def __init__(self):
        self.ues = []
        self.env = None
        self.logs_path = ''
        self.taf_ue = taf_ue()
        self.ssh = None
        self.btslog = None
        self.ue_network_modes = []
        self._ran = None
        self._mode = None
        self._node = None
        self._attenuator = None
        self._dt_names = {}
        self._dt_variables = {}
        self._remote_tcpdump_path = {}
        self._avrg_tput_info = {}

    @property
    def ran(self):
        """
        Returns RAN type: classical/cloud
        :return RAN type e.g. "classical"
        :rtype: str
        """
        if not self._ran:
            ran = BuiltIn().get_variable_value("${tl.gnbs[0]}")
            self._ran = "cloud" if isinstance(ran, CloudBts) else "classical"

        return self._ran

    @property
    def mode(self):
        """
        Returns BTS configuration mode: SA/NSA/NSA+SA.
        :return: BTS configuration e.g, "SA"
        :rtype: str
        """
        if self._mode is None:
            self._mode = self._get_mode()

        return self._mode

    @property
    def node(self):
        """
        Returns Node type: gnb/enb
        :return Node Type e.g. "gnb"
        :rtype: str
        """
        if not self._node:
            gnbs = BuiltIn().get_variable_value("${tl.gnbs}")
            self._node = "gnb" if gnbs else "enb"

        return self._node

    def _handle_network_mode(self, ue_network_modes, attach_should_be_possible):
        for serial_number, network_mode in ue_network_modes.items():
            if attach_should_be_possible:
                self._change_network_mode_on_ues(serial_number=serial_number,
                                                 network_mode=network_mode)

            self.ue_network_modes.append(network_mode)

    def _handle_ue_settings_for_specific_cell(self, ue_settings):
        for ue_setting in ue_settings:
            for ue in self.ues:
                if ue_setting["serial_number"] == ue.serial_number:
                    try:
                        ue.turn_off_airplane_mode()

                        if network_mode := ue_setting.get("network_mode"):
                            if network_mode != ue.network_mode:
                                ue.change_network_mode(network_mode=ue_setting["network_mode"])
                            else:
                                log_to_console(f"No need to change the Network mode on the UE because it is already set to '{network_mode}'")

                        if access_point_name := ue_setting.get("access_point_name"):
                            if access_point_name != ue.apn:
                                apn_settings_path = ue_setting.get("apn_settings_path")
                                ue.set_apn(apn=ue_setting["access_point_name"], apn_settings_path=apn_settings_path)
                            else:
                                log_to_console(f"No need to change the APN on the UE because it is already set to '{access_point_name}'")

                    finally:
                        ue.detach()

    def _change_network_mode_on_ues(self, serial_number, network_mode):
        for ue in self.ues:
            if serial_number == ue.serial_number:
                if network_mode != ue.network_mode:
                    if not ue.ue_reservation:
                        ue.require_ue(capabilities=ue.capabilities)
                    try:
                        ue.turn_off_airplane_mode()
                        ue.change_network_mode(network_mode=network_mode)
                    finally:
                        ue.detach()
                else:
                    log_to_console(f"No need to change the Network mode on the UE because it is already set to {network_mode}")

    def _make_l3_call_attach_should_be_possible(self, called_cell, ignored_cells_on_preparation, duration, throughput,
                                                protocol, prepare_cells_to_call, tput_verification_via_btslog,
                                                udp_buffer="4M"):
        log_to_console("Executing L3 call test using UEs with serial "
                       "numbers: {}".format([ue.serial_number for ue in self.ues]))

        self.env.called_cells_distnames = [called_cell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        self._set_proper_ue_settings_before_attach(throughput=throughput,
                                                   cell_id=cell_ids[called_cell]["{}_cell".format(self.node)])

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
            ue.detach()
            remote_tcpdump_path = self._perform_attach(attach_should_be_possible=True, ue=ue)
            self._avrg_tput_info = {ue.serial_number: {called_cell.split('/')[-1]: {'DL': None, 'UL': None}}}

            self._verify_cell_id(cell_ids=cell_ids, called_cell=called_cell, ue=ue)
            self.env.handle_beamforming()
            self._execute_data_transfer_in_both_directions(throughput=throughput, duration=duration,
                                                           protocol=protocol, udp_buffer=udp_buffer, ue=ue,
                                                           tput_verification_via_btslog=tput_verification_via_btslog,
                                                           cell_id=cell_ids[called_cell]["{}_cell".format(self.node)],
                                                           cell_distname=called_cell)
            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=remote_tcpdump_path)
            ue.detach()
            self.env.verify_pcap(cell_distname=called_cell, pcap_path=local_pcap_path, attach_should_be_possible=True)

            log_to_console("Success! L3 call procedure to cell {} executed "
                           "properly on UE with SN {}".format(called_cell, ue.serial_number))
            self._set_test_message_in_log_html(f"Average tput - {sub(r'[{}]', '', str(self._avrg_tput_info))}")

        log_to_console("L3 call to cell: {} executed properly on all UEs".format(called_cell))
        self.env.clean_up_after_call(close_connection_to_bts=False)

    def _make_l3_call_attach_should_not_be_possible(self, called_cell, prepare_cells_to_call,
                                                    ignored_cells_on_preparation):
        self.env.called_cells_distnames = [called_cell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()
        elif self.mode == "NSA" and "NRCELL" in called_cell:
            self.env.prepare_called_nrcell_from_enb_side(called_cell_distname=called_cell)

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
            ue.detach()
            remote_tcpdump_path = self._perform_attach(attach_should_be_possible=False, ue=ue)

            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=remote_tcpdump_path)
            ue.detach()
            self.env.verify_pcap(
                cell_distname=called_cell, pcap_path=local_pcap_path, attach_should_be_possible=False)

        log_result("Attach to cell: {} NOT possible (AS INTENDED!)".format(called_cell))

    @log_input_and_output
    def _set_proper_ue_settings_before_attach(self, throughput, cell_id):
        try:
            ue_settings_for_called_cell = throughput[str(cell_id)]["ues"]
            log_to_console("Changing UE settings as specified: {}".format(throughput[str(cell_id)]["ues"]))
            self._handle_ue_settings_for_specific_cell(ue_settings=ue_settings_for_called_cell)
        except KeyError:
            pass

    def _execute_data_transfer_in_both_directions(self, throughput, duration, protocol, udp_buffer, ue,
                                                  tput_verification_via_btslog, cell_id, cell_distname):
        deviation, dl_throughput, ul_throughput = self._prepare_data_transfer_variables(
            cell_id=str(cell_id), throughput=throughput)

        self._test_data_transfer(direction="DL", deviation=deviation, duration=duration, throughput=dl_throughput,
                                 protocol=protocol, udp_buffer=udp_buffer, ue=ue,
                                 tput_verification_via_btslog=tput_verification_via_btslog, cell_id=cell_id,
                                 cell_distname=cell_distname)
        self._test_data_transfer(direction="UL", duration=duration, deviation=deviation, throughput=ul_throughput,
                                 protocol=protocol, udp_buffer=udp_buffer, ue=ue,
                                 tput_verification_via_btslog=tput_verification_via_btslog, cell_id=cell_id,
                                 cell_distname=cell_distname)

    def _attach_all_ues_and_execute_parallel_data_transfer_in_both_directions(self, dl_throughput, ul_throughput,
                                                                              deviation, cell_ids, duration, protocol,
                                                                              udp_buffer, called_cell):
        log_to_console("Attaching all UEs and executing parallel data transfer in both directions")
        for ue in self.ues:
            ue.attach(attach_should_be_possible=True)
            self._verify_cell_id(cell_ids=cell_ids, called_cell=called_cell, ue=ue)

        log_to_console("Starting parallel DL data transfer...")
        self._test_parallel_data_transfer(throughput=dl_throughput, deviation=deviation, duration=duration,
                                          protocol=protocol, udp_buffer=udp_buffer, direction="dl")

        log_to_console("Starting parallel UL data transfer...")
        self._test_parallel_data_transfer(throughput=ul_throughput, deviation=deviation, duration=duration,
                                          protocol=protocol, udp_buffer=udp_buffer, direction="ul")

    def _verify_cell_id(self, cell_ids, called_cell, ue):
        if self.node == "gnb":
            if self.mode == "NSA" and "NRCELL" in called_cell:
                self._verify_cell_id_on_ue(cell_id=cell_ids[called_cell]["enb_cell"], ue=ue)
            else:
                self._verify_cell_id_on_ue(cell_id=cell_ids[called_cell]["gnb_cell"], ue=ue)
        else:
            self._verify_cell_id_on_ue(cell_id=cell_ids[called_cell]["enb_cell"], ue=ue)

    @log_input_and_output
    def _verify_cell_id_on_ue(self, cell_id, ue):
        log_to_console("Verifying if UE with SN {} is attached to correct cell".format(ue.serial_number))

        ue_cell_id = ue.get_cell_id()
        if int(cell_id) != int(ue_cell_id):
            raise IncorrectCellId("UE with SN {} is attached to the wrong cell! Called cell ID: {} "
                                  "attached cell ID: {}".format(ue.serial_number, cell_id, ue_cell_id))

        log_result("UE with SN {} is attached to correct cell: {}".format(ue.serial_number, cell_id))

    def _perform_attach(self, attach_should_be_possible, ue):
        log_to_console("Performing attach using UE with SN {}".format(ue.serial_number))
        remote_tcpdump_path = self.ssh.start_tcpdump_and_get_filepath()
        ue.attach(attach_should_be_possible=attach_should_be_possible)

        return remote_tcpdump_path

    @log_input_and_output
    def _get_mode(self):
        connection = ApiConnectionFactory.create_connection(ran=self.ran, node=self.node)
        alias = "call_manager"
        connection.connect_to(name=alias)

        if self.ran == "classical":
            return self._get_mode_for_classical_ran(connection=connection, alias=alias)

        if self.ran == "cloud":
            return self._get_mode_for_cloud_ran(connection=connection)

    def _get_mode_for_classical_ran(self, connection, alias):
        if self.node == "gnb":
            mode = connection.get_bts_info(connection=alias)["gNbCuType"]
            if mode == "SA+NSA":
                return self._get_mode_from_ue_network_mode()
            return mode
        else:
            return ""

    def _get_mode_for_cloud_ran(self, connection):
        instance_id = BuiltIn().get_variable_value("${tl.gnbs[0].dus[0].instance_id}")
        distname = "MRBTS-{0}/NRBTS-{0}".format(instance_id)
        for alias in connection.admin_du_aliases.values():
            try:
                return connection.admin_du.search_parameter_of_current_plan(mo_dn=distname, para_name="gNbCuType",
                                                                            vdu_connection=alias)
            except KeyError:
                pass

    def _get_mode_from_ue_network_mode(self):
        setups = self._get_setups()
        if len(set(setups)) > 1:
            raise ConflictingUeNetworkModes("UE network modes that you passed would require the use of both SA and"
                                            " NSA setup - this is not supported yet! Try choosing different network "
                                            "modes for one of the UEs or contact taf.rfrl.l3_call developers")
        return "".join(setups)

    def _get_setups(self):
        sa_modes = ["NR_only", "LTE_only"]
        nsa_modes = ["NR_LTE"]

        setups = []
        if self.ue_network_modes:
            for network_mode in self.ue_network_modes:
                if network_mode in sa_modes:
                    setups.append("SA")
                elif network_mode in nsa_modes:
                    setups.append("NSA")
                else:
                    raise UnrecognizedUeNetworkMode("{} UE network mode is not supported, please choose the supported "
                                                    "one or contact taf.rfrl.l3_call developers".format(network_mode))
        else:
            raise UeNetworkModeMissing("Detected gnbCuType: SA+NSA, please deliver ue_network_modes "
                                       "argument to enable the choice of proper setup!")
        return list(set(setups))

    def _test_data_transfer(self, direction, duration, throughput, deviation, protocol, udp_buffer, ue,
                            tput_verification_via_btslog=False, cell_id=None, cell_distname=None):
        log_to_console("Starting {} data transfer on UE with SN {}".format(direction, ue.serial_number))

        if ue.apn:
            log_to_console("Starting data transfer with specified APN: {}".format(ue.apn))
        dt_name = ue.start_data_transfer(direction=direction,
                                         duration=duration,
                                         throughput=throughput,
                                         protocol=protocol,
                                         udp_buffer=udp_buffer,
                                         apn=ue.apn)

        ue.check_data_transfer_is_alive(dt_name=dt_name)
        if tput_verification_via_btslog:
            self.btslog = BtsLogFactory().create_btslog(duration=duration,
                                                        direction=direction,
                                                        throughput=throughput,
                                                        deviation=deviation,
                                                        cell_distname=cell_distname,
                                                        cell_id=cell_id,
                                                        logs_path=self.logs_path)

        ue.await_data_transfer_finish(dt_name=dt_name)

        if not tput_verification_via_btslog:
            log_to_console("Verifying average throughput value with deviation: {} using iperf".format(deviation))
            ue.verify_average_throughput_with_deviation_using_iperf(dt_name=dt_name, throughput=throughput,
                                                                    deviation=deviation)
            self._get_average_throughput(dt_name=dt_name, ue=ue, cell_distname=cell_distname, direction=direction)
        else:
            log_to_console("Verifying average throughput value with deviation: {} using btslog".format(deviation))
            tput = self.btslog.verify_average_tput_using_btslog()
            formatted_tput = "{:.2f} Mbits/sec".format(tput)
            self._avrg_tput_info[ue.serial_number][cell_distname.split('/')[-1]][direction] = formatted_tput
        log_result("Data transfer verified successfully!")

    def _attach_multiple_ues_to_multiple_cells_and_test_data_transfer(self, data_transfer_variables, cells_to_ues,
                                                                      cell_ids, duration, protocol, udp_buffer):

        if is_called_cells_preparation_required := len(self.env.called_cells_distnames) > 1:
            self.env.make_selected_cells_barred(cells_distnames=cells_to_ues.keys())
        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                self._get_cell_dedicated_for_ue(cells_to_ues=cells_to_ues, ue=ue)
                if is_called_cells_preparation_required:
                    self.env.make_selected_cells_unbarred(cells_distnames=[ue.cell])
                self._attach_ue_and_verify_if_attached_to_correct_cell(ue=ue, cell_ids=cell_ids,
                                                                       cell_distname=ue.cell)
                if is_called_cells_preparation_required:
                    self.env.make_selected_cells_barred(cells_distnames=[ue.cell])
        if is_called_cells_preparation_required:
            self.env.make_selected_cells_unbarred(cells_distnames=cells_to_ues.keys())

        dl_dt_names = {}
        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                log_to_console("Starting DL data transfer on UE with SN: {}".format(ue.serial_number))
                dl_dt_names[ue.cell] = ue.start_data_transfer(
                    direction="dl",
                    duration=duration,
                    throughput=data_transfer_variables[ue.cell]["dl_throughput"],
                    protocol=protocol,
                    udp_buffer=udp_buffer
                )

        log_to_console("Waiting for DL data transfer to finish on all UEs...")
        for called_cell, dt_name in dl_dt_names.items():
            self.taf_ue.await_data_transfer_finish(dt_name=dt_name)

        ul_dt_names = {}
        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                log_to_console("Starting UL data transfer on UE with SN: {}".format(ue.serial_number))
                ul_dt_names[ue.cell] = ue.start_data_transfer(
                    direction="ul",
                    duration=duration,
                    throughput=data_transfer_variables[ue.cell]["ul_throughput"],
                    protocol=protocol,
                    udp_buffer=udp_buffer
                )

        log_to_console("Waiting for UL data transfers to finish on all UEs...")
        for cell, dt_name in ul_dt_names.items():
            self.taf_ue.await_data_transfer_finish(dt_name=dt_name)

        self._verify_average_tput_for_multiple_cells_and_multiple_ues(
            dl_dt_names=dl_dt_names, ul_dt_names=ul_dt_names,
            data_transfer_variables=data_transfer_variables
        )

    def _attach_super_subcell_and_test_data_transfer(self, cell_id, subcell_id, cell_distname, throughputs, duration,
                                                     protocol,
                                                     udp_buffer):
        deviation, dl_throughput, ul_throughput = self._prepare_data_transfer_variables(
            cell_id=str(cell_id), throughput=throughputs)

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_subcell_{}_{}.pcap".format(subcell_id, ue.alias)
            self._avrg_tput_info = {
                ue.serial_number: {cell_distname.split('/')[-1]: {'Subcell_id': subcell_id, 'DL': None, 'UL': None}}}
            remote_tcpdump_path = self.ssh.start_tcpdump_and_get_filepath()

            ue.attach(attach_should_be_possible=True)
            self._test_data_transfer(direction="DL", duration=duration, throughput=dl_throughput, deviation=deviation,
                                     protocol=protocol, udp_buffer=udp_buffer, ue=ue, cell_distname=cell_distname)

            self._test_data_transfer(direction="UL", duration=duration, throughput=ul_throughput, deviation=deviation,
                                     protocol=protocol, udp_buffer=udp_buffer, ue=ue, cell_distname=cell_distname)

            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=remote_tcpdump_path)
            ue.detach()
            self.env.verify_pcap(cell_distname=cell_distname, pcap_path=local_pcap_path, attach_should_be_possible=True)

            log_to_console("Success! L3 call procedure to super subcell {} executed "
                           "properly on UE with SN {}".format(subcell_id, ue.serial_number))
            self._set_test_message_in_log_html(f"Average tput - {sub(r'[{}]', '', str(self._avrg_tput_info))}")

    def _test_parallel_data_transfer(self, throughput, deviation, duration, protocol, udp_buffer, direction):
        dt_names = []
        for ue in self.ues:
            if ue.apn:
                log_to_console("Starting data transfer with specified APN: {}".format(ue.apn))
            dt_names.append(ue.start_data_transfer(direction=direction, duration=duration, throughput=throughput,
                                                   protocol=protocol, udp_buffer=udp_buffer, apn=ue.apn))

        log_to_console("Waiting for all data transfers to finish...")
        for dt_name in dt_names:
            self.taf_ue.check_data_transfer_is_alive(dt_name=dt_name)
            self.taf_ue.await_data_transfer_finish(dt_name=dt_name)

        log_to_console("Verifying average throughput value with deviation: {} on all UEs".format(deviation))
        for dt_name in dt_names:
            self.taf_ue.verify_average_throughput_with_deviation(dt_name, throughput, deviation)

    @log_input_and_output
    def _prepare_data_transfer_variables(self, cell_id, throughput):
        return throughput[cell_id]["deviation"], \
            throughput[cell_id]["throughput"]["downlink"], throughput[cell_id]["throughput"]["uplink"]

    @log_input_and_output
    def _prepare_data_transfer_variables_when_calling_more_than_one_cell(self, called_cells_distnames, cell_ids,
                                                                         throughput):
        data_transfer_variables = {}
        for called_cell in called_cells_distnames:
            cell_id = cell_ids[called_cell]["{}_cell".format(self.node)]
            data_transfer_variables[called_cell] = {}
            data_transfer_variables[called_cell]["deviation"] = throughput[str(cell_id)]["deviation"]
            data_transfer_variables[called_cell]["dl_throughput"] = throughput[str(cell_id)]["throughput"]["downlink"]
            data_transfer_variables[called_cell]["ul_throughput"] = throughput[str(cell_id)]["throughput"]["uplink"]

        return data_transfer_variables

    def _attach_ue_and_verify_if_attached_to_correct_cell(self, ue, cell_ids, cell_distname):
        log_to_console("Performing attach to UE with SN: {}".format(ue.serial_number))
        ue.attach(attach_should_be_possible=True)
        self._verify_cell_id(cell_ids=cell_ids, called_cell=cell_distname, ue=ue)

    def _verify_average_tput_for_multiple_cells_and_multiple_ues(self, dl_dt_names, ul_dt_names,
                                                                 data_transfer_variables):
        log_to_console("Verifying average DL throughput")
        for cell, dt_name in dl_dt_names.items():
            self.taf_ue.verify_average_throughput_with_deviation(
                dt_name,
                data_transfer_variables[cell]["dl_throughput"],
                data_transfer_variables[cell]["deviation"]
            )

        log_to_console("Verifying average UL throughput")
        for cell, dt_name in ul_dt_names.items():
            self.taf_ue.verify_average_throughput_with_deviation(
                dt_name,
                data_transfer_variables[cell]["ul_throughput"],
                data_transfer_variables[cell]["deviation"]
            )
        log_result("Data transfer in both directions verified successfully!")

    @log_input_and_output
    def _get_cell_dedicated_for_ue(self, cells_to_ues, ue):
        for cell, ue_serial_number in cells_to_ues.items():
            if ue_serial_number == ue.serial_number:
                ue.cell = cell

    def _detach_all_ues(self):
        for ue in self.ues:
            ue.detach()

    def _execute_data_transfer_in_one_direction(self, throughput, direction, duration, protocol, udp_buffer, ue,
                                                linux_congestion):
        log_to_console("Starting {} data transfer on UE with SN {}".format(direction, ue.serial_number))

        if ue.alias not in self._dt_names:
            self._dt_names[ue.alias] = {}

        if ue.apn:
            log_to_console("Starting data transfer with specified APN: {}".format(ue.apn))
        self._dt_names[ue.alias][direction] = ue.start_data_transfer(throughput=throughput,
                                                                     direction=direction,
                                                                     duration=duration,
                                                                     protocol=protocol,
                                                                     udp_buffer=udp_buffer,
                                                                     apn=ue.apn,
                                                                     linux_congestion=linux_congestion)

    @staticmethod
    def _validate_data_transfer_direction(direction):
        if direction not in ["UL", "DL", "UL_DL", "DL_UL"]:
            raise IncorrectDataTransferDirection("'{}' is not valid data transfer direction.".format(direction))

    @staticmethod
    def _validate_called_cell_or_cells_to_ues(called_cell, cells_to_ues):
        if called_cell == cells_to_ues is None:
            raise ValueError("At least one `called_cell` or `cells_to_ues` parameter must be provided")

    def _clean_data_transfer_aliases_for_ue(self, ue):
        self._dt_names[ue.alias] = {}

    def _set_all_attenuator_ports_to_chosen_mode(self, mode):
        log_to_console("Setting all attenuator ports to {} mode".format(mode))
        for cell, subcells in self._attenuator.config.items():
            for subcell, antenna_config in subcells.items():
                for antenna in antenna_config:
                    self._attenuator.set_attenuation_on_port(port=antenna["port"], value_db=antenna[mode])

    def _set_chosen_attenuation_mode_on_chosen_port_numbers(self, mode, ports):
        log_to_console("Setting attenuation on ports: {} to {} mode".format(ports, mode))
        for port in ports:
            for cell, subcells in self._attenuator.config.items():
                for subcell, antenna_config in subcells.items():
                    for antenna in antenna_config:
                        if antenna["port"] == port:
                            self._attenuator.set_attenuation_on_port(port=port, value_db=antenna[mode])

    def _set_test_message_in_log_html(self, message):
        BuiltIn().run_keyword('Set Test Message', str(message) + '\n', 'append=yes')

    def _get_average_throughput(self, dt_name, ue, cell_distname, direction):
        try:
            tput_avrg = ue.get_average_throughput(dt_name=dt_name)
            self._avrg_tput_info[ue.serial_number][cell_distname.split('/')[-1]][direction] = tput_avrg
        except Exception as e:
            log_warning('Failed to get the {} tput average from Cell {} because of {}'.format(
                direction, cell_distname.split('/')[-1], e))

    def _start_background_data_transfer_to_selected_cell(self, called_cell, direction, duration, protocol, udp_buffer,
                                                         linux_congestion):
        for ue in self.ues:
            ue.detach()
            self._remote_tcpdump_path[ue.serial_number] = self._perform_attach(attach_should_be_possible=True, ue=ue)
            self._verify_cell_id(cell_ids=self.env.cell_ids, called_cell=called_cell, ue=ue)
            self.env.handle_beamforming()

            for direct in direction.lower().split("_"):
                self._prepare_average_throughput_info_dict(ue=ue, cell_distname=called_cell, direction=direct)
                self._execute_data_transfer_in_one_direction(
                    throughput=self._dt_variables[called_cell][direct + "_throughput"],
                    direction=direct,
                    duration=duration,
                    protocol=protocol,
                    udp_buffer=udp_buffer,
                    linux_congestion=linux_congestion,
                    ue=ue
                )

    def _start_background_data_transfer_to_selected_cells_using_selected_ues(self, cells_to_ues, direction, duration,
                                                                             protocol, udp_buffer, linux_congestion):
        self._remote_tcpdump_path['multi_ue'] = self.ssh.start_tcpdump_and_get_filepath()
        self.env.make_selected_cells_barred(cells_distnames=cells_to_ues.keys())
        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                self._get_cell_dedicated_for_ue(cells_to_ues=cells_to_ues, ue=ue)
                self.env.make_selected_cells_unbarred(cells_distnames=[ue.cell])
                self._attach_ue_and_verify_if_attached_to_correct_cell(ue=ue, cell_ids=self.env.cell_ids,
                                                                       cell_distname=ue.cell)
                self.env.make_selected_cells_barred(cells_distnames=[ue.cell])
        self.env.make_selected_cells_unbarred(cells_distnames=cells_to_ues.keys())

        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                for direct in direction.lower().split("_"):
                    self._prepare_average_throughput_info_dict(ue=ue, cell_distname=ue.cell, direction=direct)
                    self._execute_data_transfer_in_one_direction(
                        throughput=self._dt_variables[ue.cell][direct + "_throughput"],
                        direction=direct,
                        duration=duration,
                        protocol=protocol,
                        udp_buffer=udp_buffer,
                        linux_congestion=linux_congestion,
                        ue=ue
                    )

    def _prepare_average_throughput_info_dict(self, ue, cell_distname, direction):
        try:
            self._avrg_tput_info[ue.serial_number][cell_distname.split('/')[-1]][direction] = None
        except KeyError:
            self._avrg_tput_info = {ue.serial_number: {cell_distname.split('/')[-1]: {direction: None}}}

    def _wait_for_data_transfer_to_selected_cell_end(self, called_cell):
        for ue in self.ues:
            for direction in self._dt_names[ue.alias].keys():
                ue.check_data_transfer_is_alive(dt_name=self._dt_names[ue.alias][direction])
                ue.await_data_transfer_finish(dt_name=self._dt_names[ue.alias][direction])

                log_to_console("Verifying average {} throughput value with deviation: {}".format(
                    direction.upper(), self._dt_variables[called_cell]["deviation"])
                )
                ue.verify_average_throughput_with_deviation_using_iperf(
                    dt_name=self._dt_names[ue.alias][direction],
                    throughput=self._dt_variables[called_cell][direction + "_throughput"],
                    deviation=self._dt_variables[called_cell]["deviation"])

                log_result("{} data transfer verified successfully!".format(direction.upper()))

            self._clean_up_after_background_l3_call_to_selected_cell(ue=ue, called_cell=called_cell)

    def _wait_for_data_transfer_to_selected_cells_using_selected_ues_end(self, cells_to_ues):
        dt_name_to_cell = {"dl": {}, "ul": {}}
        for ue in self.ues:
            for direction in self._dt_names[ue.alias].keys():
                self.taf_ue.await_data_transfer_finish(dt_name=self._dt_names[ue.alias][direction])
                dt_name_to_cell[direction][ue.cell] = self._dt_names[ue.alias][direction]
            self._clean_data_transfer_aliases_for_ue(ue)

        self._verify_average_tput_for_multiple_cells_and_multiple_ues(
            dl_dt_names=dt_name_to_cell["dl"], ul_dt_names=dt_name_to_cell["ul"],
            data_transfer_variables=self._dt_variables
        )
        self._clean_up_after_background_l3_call_to_selected_cells_using_selected_ues(cells_to_ues=cells_to_ues)

    def _clean_up_after_background_l3_call_to_selected_cell(self, ue, called_cell):
        self._clean_data_transfer_aliases_for_ue(ue)
        local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
        self.ssh.stop_tcpdump_collection_and_download_logs(
            local_path=local_pcap_path,
            remote_path=self._remote_tcpdump_path[ue.serial_number])
        ue.detach()
        self.env.verify_pcap(cell_distname=called_cell, pcap_path=local_pcap_path,
                             attach_should_be_possible=True)

        log_to_console("Success! Background L3 call procedure to cell {} executed "
                       "properly on UE with SN {}".format(called_cell, ue.serial_number))

    def _clean_up_after_background_l3_call_to_selected_cells_using_selected_ues(self, cells_to_ues):
        local_pcap_path = self.logs_path + "/log_multi_cell_multi_ue.pcap"
        self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                           remote_path=self._remote_tcpdump_path['multi_ue'])
        self._detach_all_ues()
        for called_cell in self.env.called_cells_distnames:
            self.env.verify_pcap(cell_distname=called_cell, pcap_path=local_pcap_path,
                                 attach_should_be_possible=True)

        log_to_console("Success! Background L3 Call procedure executed properly on "
                       "each of the cell-UE pairs: {}".format(cells_to_ues))

    def _stop_background_l3_call_and_verify_results_for_selected_cell(self, called_cell,
                                                                      skip_results_verification=False):
        for ue in self.ues:
            for direction in self._dt_names[ue.alias].keys():
                log_to_console("Stopping data transfer with alias: {} in direction: {}".format(
                    self._dt_names[ue.alias][direction], direction))
                ue.stop_data_transfer(dt_name=self._dt_names[ue.alias][direction])

                if not skip_results_verification:
                    log_to_console("Verifying average {} throughput value with deviation: {}".format(
                        direction.upper(), self._dt_variables[called_cell]["deviation"])
                    )
                    ue.verify_average_throughput_with_deviation_using_iperf(
                        dt_name=self._dt_names[ue.alias][direction],
                        throughput=self._dt_variables[called_cell][direction + "_throughput"],
                        deviation=self._dt_variables[called_cell]["deviation"])

                    log_result("{} data transfer verified successfully!".format(direction.upper()))

            self._clean_up_after_background_l3_call_to_selected_cell(ue=ue, called_cell=called_cell)

    def _stop_background_l3_call_and_verify_results_for_selected_ue_and_cell_pair(self, cells_to_ues,
                                                                                  skip_results_verification=False):
        dt_name_to_cell = {"dl": {}, "ul": {}}
        for ue in self.ues:
            for direction in self._dt_names[ue.alias].keys():
                log_to_console("Stopping data transfer with alias: {} in direction: {}".format(
                    self._dt_names[ue.alias][direction], direction))
                ue.stop_data_transfer(dt_name=self._dt_names[ue.alias][direction])
                dt_name_to_cell[direction][ue.cell] = self._dt_names[ue.alias][direction]
            self._clean_data_transfer_aliases_for_ue(ue)

            if not skip_results_verification:
                self._verify_average_tput_for_multiple_cells_and_multiple_ues(
                    dl_dt_names=dt_name_to_cell["dl"], ul_dt_names=dt_name_to_cell["ul"],
                    data_transfer_variables=self._dt_variables
                )
        self._clean_up_after_background_l3_call_to_selected_cells_using_selected_ues(cells_to_ues=cells_to_ues)

    def _get_cell_name(self, ue, called_cell):
        return called_cell.split('/')[-1] if called_cell else ue.cell.split('/')[-1]

    def _get_deviation(self, cell_distname):
        return int(self._dt_variables[cell_distname]["deviation"].replace("%", ""))

    def _get_expected_tput(self, cell_distname, direction):
        return float(self._dt_variables[cell_distname][direction + "_throughput"].split(" ")[0])

    def _make_iot_l3_call_attach_should_be_possible(self, called_cell, duration, prepare_cells_to_call,
                                                    ignored_cells_on_preparation):
        log_to_console("Executing IoT L3 call test using UEs with serial "
                       "numbers: {}".format([ue.serial_number for ue in self.ues]))

        self.env.called_cells_distnames = [called_cell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
            ue.detach()
            remote_tcpdump_path = self._perform_attach(attach_should_be_possible=True, ue=ue)

            self._verify_cell_id(cell_ids=cell_ids, called_cell=called_cell, ue=ue)
            self._execute_ping_test_from_appserv_to_ue_and_validate_result(ue=ue, duration=duration)
            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=remote_tcpdump_path)
            ue.detach()
            self.env.verify_pcap(cell_distname=called_cell, pcap_path=local_pcap_path, attach_should_be_possible=True)

            log_to_console("Success! L3 call procedure to IoT cell {} executed "
                           "properly on UE with SN {}".format(called_cell, ue.serial_number))

        log_to_console("L3 call to IoT cell: {} executed properly on all UEs".format(called_cell))

    def _make_iot_l3_call_attach_should_not_be_possible(self, called_cell, prepare_cells_to_call,
                                                        ignored_cells_on_preparation):
        self.env.called_cells_distnames = [called_cell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
            ue.detach()
            remote_tcpdump_path = self._perform_attach(attach_should_be_possible=False, ue=ue)

            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=remote_tcpdump_path)
            ue.detach()
            self.env.verify_pcap(
                cell_distname=called_cell, pcap_path=local_pcap_path, attach_should_be_possible=False)

        log_result("Attach to IoT cell: {} NOT possible (AS INTENDED!)".format(called_cell))

    def _attach_multiple_ues_to_multiple_iot_cells_and_verify_ping(self, cells_to_ues, cell_ids, duration):

        if is_called_cells_preparation_required := len(self.env.called_cells_distnames) > 1:
            self.env.make_selected_cells_barred(cells_distnames=cells_to_ues.keys())
        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                self._get_cell_dedicated_for_ue(cells_to_ues=cells_to_ues, ue=ue)
                if is_called_cells_preparation_required:
                    self.env.make_selected_cells_unbarred(cells_distnames=[ue.cell])
                self._attach_ue_and_verify_if_attached_to_correct_cell(ue=ue, cell_ids=cell_ids,
                                                                       cell_distname=ue.cell)
                if is_called_cells_preparation_required:
                    self.env.make_selected_cells_barred(cells_distnames=[ue.cell])
        if is_called_cells_preparation_required:
            self.env.make_selected_cells_unbarred(cells_distnames=cells_to_ues.keys())

        for ue in self.ues:
            if ue.serial_number in cells_to_ues.values():
                log_to_console("Starting ping test on UE with SN: {}".format(ue.serial_number))
                self._execute_ping_test_from_appserv_to_ue_and_validate_result(ue=ue, duration=duration)

    def _execute_ping_test_from_appserv_to_ue_and_validate_result(self, ue, duration, ue_data_transfer_element=0):
        ue_ip = ue.get_ue_ip()
        log_to_console("Ue IP to make ping test: {}".format(ue_ip))
        result = self._ping_ue_host_via_ssh(remote_host=ue.tl_ue.data_transfer[ue_data_transfer_element].app_server.address,
                                            username=ue.tl_ue.data_transfer[ue_data_transfer_element].app_server.user,
                                            password=ue.tl_ue.data_transfer[ue_data_transfer_element].app_server.password,
                                            target_ue_host=ue_ip,
                                            duration=duration)
        log_result("Ue host ping result: {}".format(result))
        ping_statistics = self._get_ping_statistics(result)
        self._validate_ping_statistics(ping_statistics)

    def _ping_ue_host_via_ssh(self, remote_host, username, password, target_ue_host, duration):
        duration_in_seconds = int(timestr_to_secs(duration))
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh.connect(hostname=remote_host, username=username, password=password)
        log_to_console("Ping duration: {} seconds".format(duration_in_seconds))
        try:
            stdin, stdout, stderr = ssh.exec_command(command=f'ping -c {duration_in_seconds} {target_ue_host}')
            output = stdout.read().decode()
            error = stderr.read().decode()
        finally:
            ssh.close()

        if output:
            return output
        else:
            raise PingExecutionFailed(f"Ping command execution failed with error: {error}")

    def _get_ping_statistics(self, result):
        for line in result.splitlines():
            if "packets transmitted" and "packet loss" in line:
                ping_stats = [ping_stat.strip() for ping_stat in line.split(",")]
                return ping_stats

        raise PingStatisticsNotFound(f"No ping statistics found in the result: {result}")

    def _validate_ping_statistics(self, ping_stats):
        if "0% packet loss" in ping_stats:
            log_result("Ping validation succeeded: 0% packet loss detected.")
        else:
            raise PingValidationFailed(f"Ping validation failed: Packet loss detected: {ping_stats}")
